#!/usr/bin/env bun
// init-project — self-contained project bootstrap (single file, curl-pipe safe).
// Layers: 1) machine: ensure/update the 9 tool CLIs (NO ~/ dotfile config ever)
//         2) project MCP: .pi/mcp.json + .agents/mcp_config.json (env-ref credentials)
//         3) project skills: skills embedded as payload -> .agents/skills/
//         4) repo inits: graft build / qmd init . / codegraph init (marker-gated)
// Run: curl -fsSL <raw-url>/init-project.ts | bun    (from a project root)
//      bun init-project.ts
import { spawnSync } from "node:child_process";
import { chmodSync, existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { homedir, tmpdir } from "node:os";

const isWin = process.platform === "win32";
// Curl-pipe: script may have no real path; project root = invocation CWD.
const PROJECT_ROOT = process.cwd();
// --prune = full install of our surfaces (managed keys replaced, AGENTS.md book reinstalled).
// Default = update ours, add missing, keep yours - it deletes nothing except stale marked skills.
// Unknown arguments are ignored: this script is also invoked by other tooling.
const PRUNE = Bun.argv.includes("--prune");

function log(msg: string): void {
  console.log(`[init-project] ${msg}`);
}
function warn(msg: string): void {
  console.error(`[init-project] WARN: ${msg}`);
}
function fail(msg: string): never {
  console.error(`[init-project] ERROR: ${msg}`);
  process.exit(1);
}

// Run a command; returns {code, stdout, stderr}. Never throws.
function run(cmd: string, args: string[], cwd?: string) {
  const r = spawnSync(cmd, args, {
    encoding: "utf8",
    cwd,
    // Windows: npm/npx/uv are .cmd shims — shell resolves them. POSIX: direct exec.
    shell: isWin,
  });
  return { code: r.status ?? 1, stdout: r.stdout ?? "", stderr: r.stderr ?? "" };
}

